        StreamConnect["Connect Cluster<br/>(Capture and sink connectors)"]
        TopicMgmt["Topic Management<br/>(Streaming topic operator)"]
        UserMgmt["User/ACL Management<br/>(Streaming user operator)"]
    end

    DPS["Division Proxy Services"]
    DS["Domain Services"]
    IFS["Identity Federation Service"]
    CES["Consent Event Service"]
    RMS["Read Model Services"]
